const payload = $input.first().json;
const posts = Array.isArray(payload.posts) ? payload.posts : [];
if (!Array.isArray(posts)) {
  throw new Error('Threads miner must return posts as a JSON array.');
}

return posts
  .filter(p => p && p.id && p.url)
  .map(p => ({ json: p }));

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

const env = (typeof process !== 'undefined' && process.env) ? process.env : {};
const enabled = ['1', 'true', 'yes'].includes(String(env.THREADS_CLASSIFIER_ENABLED || 'true').trim().toLowerCase());
const model = String(env.THREADS_CLASSIFIER_MODEL || 'gemini-2.5-flash-lite').trim();
const envTrendBrief = cleanText(env.THREADS_TREND_BRIEF || '');
const priorityTopics = cleanText(env.THREADS_PRIORITY_TOPICS || '');

return $input.all().map(item => {
  const preview = cleanText(item.json.text_preview || '');
  const fitScore = Number(item.json.content_fit_score || 0);
  const fitTags = Array.isArray(item.json.content_fit_tags) ? item.json.content_fit_tags : [];
  const engagementScore = Number(item.json.engagement_score || 0);
  const engagementMetrics = Array.isArray(item.json.engagement_metrics) ? item.json.engagement_metrics : [];
  const strongestMetric = Number(item.json.engagement_strongest_metric || 0);
  const metricCount = Number(item.json.engagement_metric_count || 0);
  const trendBrief = cleanText(item.json.trend_brief || envTrendBrief);
  const searchKeyword = cleanText(item.json.search_keyword || '');
  const queryMatch = item.json.query_match === true || fitTags.includes('query-match');

  item.json._classifier = {
    enabled,
    model,
    preview,
    fitScore,
    fitTags,
    engagementScore,
    engagementMetrics,
    strongestMetric,
    metricCount,
    trendBrief,
    priorityTopics,
    searchKeyword,
    queryMatch,
    prompt: [
      'Ban la bo loc noi dung cho kenh video ngan tieng Viet.',
      'Hay danh gia preview cua mot bai Threads xem co nen dua vao pipeline lam video binh luan/storytime dang hot khong.',
      'CHI GIU bai co it nhat mot trong cac diem manh: tranh luan ro, cau hoi mo de nguoi xem binh luan, xung dot/plot twist, van de xa hoi dang nong, hoac bai hoc/kinh nghiem co tinh bat ngo va khong bi self-promo.',
      'discussion phai co y kien trai chieu hoac cau hoi that su dang ban. story_hot phai co dien bien gay to mo, drama, plot twist, rui ro, sai lam, ket qua bat ngo, hoac bai hoc khien nguoi xem muon nghe tiep. topic_hot phai la van de cong chung co kha nang gay tranh luan.',
      trendBrief ? 'CURRENT_TREND_BRIEF: ' + trendBrief : 'CURRENT_TREND_BRIEF: none',
      priorityTopics ? 'PRIORITY_TOPICS: ' + priorityTopics : 'PRIORITY_TOPICS: none',
      searchKeyword ? 'MANUAL_SEARCH_KEYWORD: ' + searchKeyword : 'MANUAL_SEARCH_KEYWORD: none',
      searchKeyword ? 'NEU co MANUAL_SEARCH_KEYWORD thi chi keep bai bam sat keyword do. Bai hay nhung lech keyword van phai reject.' : 'Khong co manual keyword, danh gia theo kha nang lam video.',
      searchKeyword ? ('QUERY_MATCH_SIGNAL: ' + (queryMatch ? 'matched' : 'not_matched')) : 'QUERY_MATCH_SIGNAL: none',
      'Neu preview lien quan ro den CURRENT_TREND_BRIEF va van tao duoc tranh luan/storytime, uu tien keep hon cac bai evergreen ngang diem.',
      'Uu tien bai co mass appeal: anh huong tien bac, nha cua, giao thong, cong viec, gia dinh, suc khoe, giao duc, chinh sach, do thi, an toan, tam linh/kinh di, hoac van de nhieu nguoi Viet co the lien he ngay.',
      'BAT BUOC reject neu preview chi hot trong fandom/cong dong nho, drama idol/nhom nhac, cau chuyen noi bo, hoac engagement cao nhung nguoi ngoai khong co ly do quan tam.',
      'BAT BUOC reject neu preview chi la ke hanh trinh ca nhan truyen cam hung, quang ba podcast/kenh/brand, cam on/chia se chung chung, meo nghe nghiep qua hien lanh, hoac bai khong tao duoc cau hoi binh luan ro rang.',
      'BAT BUOC reject neu strongest_metric < 1000 hoac engagement chu yeu la tong nhieu metric nho, tru khi noi dung cuc ky gay tranh luan/viral.',
      'BAT BUOC reject neu preview chi la thong bao, lich, danh sach (list), giai thich kien thuc trung tinh, hoac chi neu thong tin ma khong co xung dot/cam xuc/cau hoi thuc su. Vi du: lich thi THPTQG, huong dan dang ky, gio mo cua, thong bao chinh sach — reject tru khi co phan ung cong dong ro rang kem theo trong preview.',
      'BAT BUOC reject neu preview chi la cau hoi gia dinh giai tri (neu ban co 10 ty ban lam gi, ban chon A hay B, rank cac lua chon...) ma khong co cau chuyen that, su kien that, hoac hau qua that di kem. Loai nay thu hut like nhung khong co chat lieu lam storytime/binh luan.',
      'BAT BUOC reject neu preview co dau hieu bai cu ro rang: nhac den su kien da ket thuc nhieu thang truoc, cap nhat cu, hoac thong tin het hieu luc — tru khi la bai hoc evergreen cuc ky manh (co xung dot/drama/bai hoc con nguyen gia tri) va fit_score >= 6.',
      'Duoc phep dung fit score va engagement lam ngu canh phu, nhung quyet dinh chinh phai dua tren kha nang giu chan nguoi xem va tao binh luan.',
      'Tra ve DUY NHAT mot JSON hop le theo schema: {"decision":"keep|reject","angle":"discussion|story_hot|topic_hot|reject","confidence":0.0,"reason":"..."}.',
      'reason phai ngan gon, neu reject thi noi ro ly do chinh (mong/list/cu/hypothetical/fandom/lech-keyword/...).',
    ].join(' '),
  };

  return item;
});

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function parseJsonCandidate(text) {
  const cleaned = cleanText(text);
  if (!cleaned) return null;

  const fencedMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const jsonSource = fencedMatch ? fencedMatch[1] : cleaned;
  const braceMatch = jsonSource.match(/\{[\s\S]*\}/);
  const candidate = braceMatch ? braceMatch[0] : jsonSource;

  try {
    const parsed = JSON.parse(candidate);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (error) {
    return null;
  }
}

function extractTextDeep(value, bucket = []) {
  if (typeof value === 'string') {
    const cleaned = cleanText(value);
    if (cleaned) bucket.push(cleaned);
    return bucket;
  }

  if (!value || typeof value !== 'object') return bucket;
  if (Array.isArray(value)) {
    value.forEach(entry => extractTextDeep(entry, bucket));
    return bucket;
  }

  Object.values(value).forEach(entry => {
    if (typeof entry === 'string') {
      const cleaned = cleanText(entry);
      if (cleaned) bucket.push(cleaned);
    } else if (entry && typeof entry === 'object') {
      extractTextDeep(entry, bucket);
    }
  });
  return bucket;
}

function extractClassifierDecision(data) {
  if (!data || typeof data !== 'object') return null;

  const direct = [data.output, data.text, data.content, data.message, data.response].filter(Boolean);
  for (const candidate of direct) {
    const parsed = parseJsonCandidate(candidate);
    if (parsed) return parsed;
  }

  for (const candidate of extractTextDeep(data, [])) {
    const parsed = parseJsonCandidate(candidate);
    if (parsed) return parsed;
  }

  return null;
}

const kept = [];

for (const item of $input.all()) {
  const classifier = item.json._classifier || {};
  const preview = cleanText(classifier.preview || item.json.text_preview || '');
  const fitScore = Number(classifier.fitScore || item.json.content_fit_score || 0);
  const fitTags = Array.isArray(classifier.fitTags || item.json.content_fit_tags) ? (classifier.fitTags || item.json.content_fit_tags) : [];
  const strongestMetric = Number(classifier.strongestMetric || item.json.engagement_strongest_metric || 0);
  const metricCount = Number(classifier.metricCount || item.json.engagement_metric_count || 0);
  const classifierEnabled = classifier.enabled !== false;
  const searchKeyword = cleanText(classifier.searchKeyword || item.json.search_keyword || '');
  const requiresKeywordMatch = Boolean(searchKeyword);
  const queryMatch = classifier.queryMatch === true || item.json.query_match === true || fitTags.includes('query-match');
  const fallbackKeep = fitScore >= 5 && preview.length >= 140 && metricCount >= 2 && strongestMetric >= 1000 && (!requiresKeywordMatch || queryMatch) && (fitTags.includes('discussion') || fitTags.includes('story') || fitTags.includes('topic-hot') || fitTags.includes('priority-topic') || fitTags.includes('mass-appeal'));
  const parsed = classifierEnabled ? extractClassifierDecision(item.json) : null;

  let decision = fallbackKeep ? 'keep' : 'reject';
  let angle = fitTags.includes('discussion') ? 'discussion' : (fitTags.includes('story') ? 'story_hot' : ((fitTags.includes('topic-hot') || fitTags.includes('priority-topic') || fitTags.includes('mass-appeal')) ? 'topic_hot' : 'reject'));
  let confidence = fallbackKeep ? 0.6 : 0.35;
  let reason = fallbackKeep
    ? `heuristic keep fit=${fitScore} metricCount=${metricCount} strongest=${strongestMetric} tags=${fitTags.join(',') || 'none'}`
    : `heuristic reject fit=${fitScore} metricCount=${metricCount} strongest=${strongestMetric} preview_too_weak`;

  if (requiresKeywordMatch && !queryMatch) {
    decision = 'reject';
    angle = 'reject';
    confidence = Math.max(confidence, 0.8);
    reason = `reject off_keyword keyword=${searchKeyword || 'none'}`;
  } else if (strongestMetric < 1000) {
    decision = 'reject';
    angle = 'reject';
    confidence = Math.max(confidence, 0.7);
    reason = `reject strongest_metric_under_1000 strongest=${strongestMetric} total=${classifier.engagementScore || item.json.engagement_score || 0}`;
  } else if (!classifierEnabled) {
    reason = `ai disabled; ${reason}`;
  } else if (parsed) {
    const parsedDecision = cleanText(parsed.decision || '').toLowerCase();
    const parsedAngle = cleanText(parsed.angle || '').toLowerCase();
    const parsedReason = cleanText(parsed.reason || '');
    const parsedConfidence = Number(parsed.confidence || 0);
    if ((parsedDecision === 'keep' || parsedDecision === 'reject') && ['discussion', 'story_hot', 'topic_hot', 'reject'].includes(parsedAngle || 'reject')) {
      decision = parsedDecision;
      angle = parsedAngle || (parsedDecision === 'keep' ? 'discussion' : 'reject');
      confidence = Number.isFinite(parsedConfidence) ? parsedConfidence : confidence;
      reason = parsedReason || reason;
    }
  } else {
    reason = `ai fallback; ${reason}`;
  }

  item.json._classifier_decision = decision;
  item.json._classifier_angle = angle;
  item.json._classifier_confidence = Math.max(0, Math.min(1, confidence || 0));
  item.json._classifier_reason = reason;

  if (decision === 'keep' && ['discussion', 'story_hot', 'topic_hot'].includes(angle)) {
    kept.push(item);
  }
}

return kept;

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

const startMessage = [
  'Bot tìm kiếm bài Threads theo keyword bạn nhập.',
  '',
  'Cách dùng: nhập trực tiếp vào đoạn chat',
  '- <keyword>',
  '- <keyword> | <max_posts>',
  '',
  'Ví dụ:',
  '- giá vàng',
  '- giá vàng | 5',
  '',
  'Lưu ý:',
  '- Nếu không nhập số lượng, bot sẽ dùng giá trị mặc định',
  '- Bot ưu tiên các bài liên quan sát với keyword',
].join('\n');

const output = [];
for (const item of $input.all()) {
  const payload = item.json.body || item.json;
  const message = payload.message || payload.edited_message || {};
  const chat = message.chat || {};
  const from = message.from || {};
  const chatId = String(chat.id || '').trim();
  const allowedChatId = String($env.TELEGRAM_CHAT_ID || '').trim();
  const rawText = cleanText(message.text || '');

  if (allowedChatId && chatId && chatId !== allowedChatId) continue;
  if (!rawText) continue;

  if (/^\/start(?:@\w+)?(?:\s|$)/i.test(rawText)) {
    output.push({
      json: {
        mode: 'help',
        chat_id: chatId || allowedChatId,
        reply_text: startMessage,
      },
    });
    continue;
  }

  const commandMatch = rawText.match(/^\/(?:search|trend)@?\w*\s+(.+)$/i);
  const keywordText = cleanText(commandMatch ? commandMatch[1] : rawText);

  if (/^\//.test(rawText) && !commandMatch) continue;

  const parts = keywordText.split('|').map(part => cleanText(part)).filter(Boolean);
  const keyword = parts[0] || '';
  const maxPosts = Math.max(1, Math.min(50, Number(parts[1] || $env.THREADS_SEARCH_MAX_POSTS || 10) || 10));

  if (!keyword) continue;

  output.push({
    json: {
      mode: 'search',
      keyword,
      max_posts: maxPosts,
      chat_id: chatId || allowedChatId,
      requested_by: String(from.username || from.id || '').trim(),
      reply_text: 'Đã nhận keyword: ' + keyword + '. Đang tìm tối đa ' + maxPosts + ' bài Threads.',
    },
  });
}

return output;
